// Package artifacts owns immutable per-run directories and bounded file
// writes. Names are generated by the store and validated before use; path
// traversal and symlink replacement are rejected.
package artifacts

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"sync"
	"syscall"
)

// DefaultMaxBytesPerRun bounds all data written into one run directory.
const DefaultMaxBytesPerRun int64 = 10 << 20

// DefaultMaxFilesPerRun bounds the number of files in one run directory.
const DefaultMaxFilesPerRun = 64

// ErrQuota is returned when a run directory exceeds its byte budget.
var ErrQuota = errors.New("artifacts: run quota exceeded")

// ErrFileQuota is returned when a run directory exceeds its file count budget.
var ErrFileQuota = errors.New("artifacts: file count quota exceeded")

var (
	runIDPattern = regexp.MustCompile(`^run_[0-9a-f]{32}$`)
	namePattern  = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$`)
)

// Store creates and owns run directories under one configured root.
type Store struct {
	root           string
	maxBytesPerRun int64
}

// NewStore prepares the artifact root and returns a store.
func NewStore(root string, maxBytesPerRun int64) (*Store, error) {
	if root == "" || !filepath.IsAbs(root) {
		return nil, errors.New("artifacts: root must be an absolute path")
	}
	if maxBytesPerRun <= 0 {
		maxBytesPerRun = DefaultMaxBytesPerRun
	}

	clean := filepath.Clean(root)
	if err := os.MkdirAll(clean, 0o700); err != nil {
		return nil, fmt.Errorf("artifacts: create root: %w", err)
	}
	info, err := os.Lstat(clean)
	if err != nil {
		return nil, fmt.Errorf("artifacts: inspect root: %w", err)
	}
	if info.Mode()&os.ModeSymlink != 0 {
		return nil, errors.New("artifacts: root must not be a symbolic link")
	}
	if !info.IsDir() {
		return nil, errors.New("artifacts: root is not a directory")
	}
	if stat, ok := info.Sys().(*syscall.Stat_t); ok && int(stat.Uid) != os.Geteuid() {
		return nil, errors.New("artifacts: root is not owned by the current user")
	}
	if info.Mode().Perm()&0o077 != 0 {
		if err := os.Chmod(clean, 0o700); err != nil {
			return nil, fmt.Errorf("artifacts: secure root: %w", err)
		}
	}

	return &Store{root: clean, maxBytesPerRun: maxBytesPerRun}, nil
}

// MaxBytesPerRun returns the per-run artifact budget.
func (s *Store) MaxBytesPerRun() int64 { return s.maxBytesPerRun }

// Create atomically creates a new run directory with an opaque identifier.
func (s *Store) Create() (*RunDir, error) {
	for range 5 {
		id, err := newRunID()
		if err != nil {
			return nil, err
		}
		path := filepath.Join(s.root, id)
		if err := os.Mkdir(path, 0o700); err != nil {
			if errors.Is(err, os.ErrExist) {
				continue
			}
			return nil, fmt.Errorf("artifacts: create run directory: %w", err)
		}
		if err := os.Chmod(path, 0o700); err != nil {
			_ = os.RemoveAll(path)
			return nil, fmt.Errorf("artifacts: secure run directory: %w", err)
		}
		return &RunDir{
			id:       id,
			path:     path,
			maxBytes: s.maxBytesPerRun,
			maxFiles: DefaultMaxFilesPerRun,
			sizes:    make(map[string]int64),
			streams:  make(map[string]bool),
		}, nil
	}
	return nil, errors.New("artifacts: run identifier collision")
}

// Remove deletes one run directory.
func (s *Store) Remove(id string) error {
	if !runIDPattern.MatchString(id) {
		return fmt.Errorf("artifacts: invalid run id %q", id)
	}
	if err := os.RemoveAll(filepath.Join(s.root, id)); err != nil {
		return fmt.Errorf("artifacts: remove run %q: %w", id, err)
	}
	return nil
}

// Path returns the directory for a run id. It does not check existence.
func (s *Store) Path(id string) (string, error) {
	if !runIDPattern.MatchString(id) {
		return "", fmt.Errorf("artifacts: invalid run id %q", id)
	}
	return filepath.Join(s.root, id), nil
}

// RunDir is one isolated artifact directory.
type RunDir struct {
	id       string
	path     string
	maxBytes int64
	maxFiles int

	mu      sync.Mutex
	written int64
	files   int
	// sizes tracks the bytes charged per file so a rewrite credits the
	// replaced content; streams marks names held open by a QuotaWriter.
	sizes   map[string]int64
	streams map[string]bool
}

// ID returns the opaque run identifier.
func (d *RunDir) ID() string { return d.id }

// Path returns the absolute run directory.
func (d *RunDir) Path() string { return d.path }

// Written returns the number of bytes charged against the run quota.
func (d *RunDir) Written() int64 {
	d.mu.Lock()
	defer d.mu.Unlock()
	return d.written
}

// OpenWriter creates a bounded writer for a new artifact file.
func (d *RunDir) OpenWriter(name string) (*QuotaWriter, error) {
	path, err := d.safePath(name)
	if err != nil {
		return nil, err
	}

	d.mu.Lock()
	if d.files >= d.maxFiles {
		d.mu.Unlock()
		return nil, ErrFileQuota
	}
	d.files++
	d.mu.Unlock()

	file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL|syscall.O_NOFOLLOW, 0o600)
	if err != nil {
		d.mu.Lock()
		d.files--
		d.mu.Unlock()
		return nil, fmt.Errorf("artifacts: create %q: %w", name, err)
	}
	d.mu.Lock()
	d.streams[name] = true
	d.mu.Unlock()
	return &QuotaWriter{dir: d, name: name, file: file}, nil
}

// OpenRead opens an existing artifact without following a final symlink.
func (d *RunDir) OpenRead(name string) (*os.File, error) {
	path, err := d.safePath(name)
	if err != nil {
		return nil, err
	}
	file, err := os.OpenFile(path, os.O_RDONLY|syscall.O_NOFOLLOW, 0)
	if err != nil {
		return nil, fmt.Errorf("artifacts: open %q: %w", name, err)
	}
	return file, nil
}

// ReadFile reads a bounded artifact.
func (d *RunDir) ReadFile(name string) ([]byte, error) {
	file, err := d.OpenRead(name)
	if err != nil {
		return nil, err
	}
	defer file.Close()

	data, err := io.ReadAll(io.LimitReader(file, d.maxBytes+1))
	if err != nil {
		return nil, fmt.Errorf("artifacts: read %q: %w", name, err)
	}
	if int64(len(data)) > d.maxBytes {
		return nil, ErrQuota
	}
	return data, nil
}

// WriteFileAtomic writes a complete file through a temporary name and rename.
func (d *RunDir) WriteFileAtomic(name string, data []byte) error {
	path, err := d.safePath(name)
	if err != nil {
		return err
	}

	d.mu.Lock()
	defer d.mu.Unlock()

	if d.streams[name] {
		return fmt.Errorf("artifacts: %q is open for streaming and cannot be replaced", name)
	}
	previous := d.sizes[name]
	if int64(len(data)) > d.maxBytes-(d.written-previous) {
		return ErrQuota
	}

	_, statErr := os.Lstat(path)
	newFile := errors.Is(statErr, os.ErrNotExist)
	if statErr != nil && !newFile {
		return fmt.Errorf("artifacts: inspect %q: %w", name, statErr)
	}
	if newFile && d.files >= d.maxFiles {
		return ErrFileQuota
	}

	tmpName, err := randomSuffix(".tmp-")
	if err != nil {
		return err
	}
	tmpPath := filepath.Join(d.path, tmpName)
	tmp, err := os.OpenFile(tmpPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL|syscall.O_NOFOLLOW, 0o600)
	if err != nil {
		return fmt.Errorf("artifacts: create temporary file: %w", err)
	}

	cleanup := func() {
		_ = tmp.Close()
		_ = os.Remove(tmpPath)
	}
	written, err := tmp.Write(data)
	if err != nil {
		cleanup()
		return fmt.Errorf("artifacts: write %q: %w", name, err)
	}
	if written != len(data) {
		cleanup()
		return fmt.Errorf("artifacts: write %q: %w", name, io.ErrShortWrite)
	}
	if err := tmp.Sync(); err != nil {
		cleanup()
		return fmt.Errorf("artifacts: sync %q: %w", name, err)
	}
	if err := tmp.Close(); err != nil {
		_ = os.Remove(tmpPath)
		return fmt.Errorf("artifacts: close %q: %w", name, err)
	}
	if err := os.Rename(tmpPath, path); err != nil {
		_ = os.Remove(tmpPath)
		return fmt.Errorf("artifacts: publish %q: %w", name, err)
	}

	d.written += int64(len(data)) - previous
	d.sizes[name] = int64(len(data))
	if newFile {
		d.files++
	}
	return nil
}

// charge records written bytes; the caller holds d.mu.
func (d *RunDir) charge(name string, n int64) {
	d.written += n
	d.sizes[name] += n
}

func (d *RunDir) safePath(name string) (string, error) {
	if !namePattern.MatchString(name) {
		return "", fmt.Errorf("artifacts: invalid file name %q", name)
	}
	return filepath.Join(d.path, name), nil
}

// QuotaWriter enforces the run byte budget while streaming output.
type QuotaWriter struct {
	mu     sync.Mutex
	dir    *RunDir
	name   string
	file   *os.File
	closed bool
}

// Write implements io.Writer.
func (w *QuotaWriter) Write(p []byte) (int, error) {
	w.mu.Lock()
	defer w.mu.Unlock()

	if w.closed {
		return 0, os.ErrClosed
	}

	if len(p) == 0 {
		return 0, nil
	}

	w.dir.mu.Lock()
	defer w.dir.mu.Unlock()

	remaining := w.dir.maxBytes - w.dir.written
	if remaining <= 0 {
		return 0, ErrQuota
	}
	if int64(len(p)) > remaining {
		n, err := w.file.Write(p[:remaining])
		w.dir.charge(w.name, int64(n))
		if err != nil {
			return n, err
		}
		if int64(n) != remaining {
			return n, io.ErrShortWrite
		}
		return n, ErrQuota
	}

	n, err := w.file.Write(p)
	w.dir.charge(w.name, int64(n))
	if err == nil && n != len(p) {
		return n, io.ErrShortWrite
	}
	return n, err
}

// Close implements io.Closer.
func (w *QuotaWriter) Close() error {
	w.mu.Lock()
	defer w.mu.Unlock()

	if w.closed {
		return nil
	}
	w.closed = true
	w.dir.mu.Lock()
	delete(w.dir.streams, w.name)
	w.dir.mu.Unlock()
	return w.file.Close()
}

func newRunID() (string, error) {
	suffix, err := randomSuffix("")
	if err != nil {
		return "", err
	}
	return "run_" + suffix, nil
}

func randomSuffix(prefix string) (string, error) {
	var raw [16]byte
	if _, err := rand.Read(raw[:]); err != nil {
		return "", fmt.Errorf("artifacts: random: %w", err)
	}
	return prefix + hex.EncodeToString(raw[:]), nil
}
